CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, login TEXT UNIQUE NOT NULL, name TEXT NOT NULL, pass TEXT NOT NULL, salt TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'handlowiec', team TEXT NOT NULL DEFAULT 'główny', created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invites (code TEXT PRIMARY KEY, role TEXT NOT NULL, team TEXT NOT NULL, created_by INTEGER, used_by INTEGER, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reservations (parcel_id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, label TEXT, until INTEGER NOT NULL, status TEXT, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, parcel_id TEXT NOT NULL, status TEXT NOT NULL, at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ev_user ON events(user_id);
